type FloatingMessage={role:'user'|'assistant';text:string;file?:string;risk?:string;confidence?:number;recommendations?:string[];error?:boolean}
const assistantWelcome:FloatingMessage={role:'assistant',text:'Hello — I’m ShieldIQ. I can check suspicious messages, payment requests, QR codes, calls, images, audio, and PDFs. What would you like me to investigate?'}

function FloatingAssistant(){
 const [open,setOpen]=useState(false);const [input,setInput]=useState('');const [file,setFile]=useState<File|null>(null);const [loading,setLoading]=useState(false)
 const uploadRef=useRef<HTMLInputElement>(null);const endRef=useRef<HTMLDivElement>(null)
 const [messages,setMessages]=useState<FloatingMessage[]>(()=>{try{const saved=sessionStorage.getItem('shieldiq_floating_chat');return saved?JSON.parse(saved):[assistantWelcome]}catch{return [assistantWelcome]}})
 useEffect(()=>{sessionStorage.setItem('shieldiq_floating_chat',JSON.stringify(messages));if(open)endRef.current?.scrollIntoView({behavior:'smooth'})},[messages,open])
 useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[])
 const fresh=()=>{setMessages([assistantWelcome]);setInput('');setFile(null)}
 const send=async(text=input)=>{
  const prompt=text.trim()||`Please analyze the attached ${file?.type||'file'}.`;if((!text.trim()&&!file)||loading)return
  const attached=file;setMessages(current=>[...current,{role:'user',text:prompt,file:attached?.name}]);setInput('');setFile(null);setLoading(true)
  try{const result=await services.chat(prompt,attached);setMessages(current=>[...current,{role:'assistant',text:result.response,risk:result.risk_level,confidence:Math.round(result.confidence*100),recommendations:result.recommendations}])}
  catch(err){setMessages(current=>[...current,{role:'assistant',text:errorMessage(err),error:true}])}
  finally{setLoading(false)}
 }
 return <><button className={`ai-fab ${open?'active':''}`} onClick={()=>setOpen(value=>!value)} aria-label={open?'Close ShieldIQ assistant':'Ask ShieldIQ'}>{open?<X/>:<Sparkles/>}<span>{open?'Close':'Ask ShieldIQ'}</span></button>{open&&<><button className="assistant-backdrop" aria-label="Close assistant" onClick={()=>setOpen(false)}/><section className="floating-assistant" aria-label="ShieldIQ AI assistant"><header><span><Bot/></span><div><b>ShieldIQ</b><small><i/> AI public safety assistant</small></div><button onClick={fresh} title="New chat" aria-label="New chat"><MessageSquareText/></button><NavLink to="/assistant" onClick={()=>setOpen(false)} title="Open full assistant" aria-label="Open full assistant"><ArrowRight/></NavLink><button onClick={()=>setOpen(false)} aria-label="Close assistant"><X/></button></header><div className="floating-messages">{messages.map((message,index)=><div className={`floating-message ${message.role}`} key={`${message.role}-${index}`}><span>{message.role==='assistant'?<Bot/>:null}</span><div>{message.file&&<small className="floating-file"><UploadCloud/> {message.file}</small>}<p className={message.error?'message-error':''}>{message.text}</p>{message.recommendations?.length?<ul>{message.recommendations.map(item=><li key={item}>{item}</li>)}</ul>:null}{message.confidence!=null&&<footer><em className={`risk-${message.risk}`}>{message.risk} risk</em><span>{message.confidence}% confidence</span></footer>}</div></div>)}{loading&&<div className="floating-message assistant"><span><Bot/></span><div className="assistant-thinking"><i/><i/><i/></div></div>}<div ref={endRef}/></div>{messages.length===1&&<div className="floating-prompts">{['Check a suspicious message','Explain digital arrest scams','Is this payment request safe?'].map(prompt=><button key={prompt} onClick={()=>void send(prompt)}>{prompt}<ArrowRight/></button>)}</div>}{file&&<div className="floating-attachment"><UploadCloud/><span>{file.name}<small>{(file.size/1024).toFixed(1)} KB</small></span><button onClick={()=>setFile(null)}><X/></button></div>}<form className="floating-composer" onSubmit={event=>{event.preventDefault();void send()}}><input ref={uploadRef} hidden type="file" accept="image/png,image/jpeg,image/webp,audio/wav,audio/mpeg,audio/mp4,application/pdf" onChange={event=>setFile(event.target.files?.[0]||null)}/><button type="button" onClick={()=>uploadRef.current?.click()} aria-label="Attach file"><UploadCloud/></button><textarea aria-label="Message ShieldIQ" rows={1} value={input} onChange={event=>setInput(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();void send()}}} placeholder="Message ShieldIQ…"/><button className="floating-send" disabled={loading||(!input.trim()&&!file)} aria-label="Send message"><ArrowRight/></button></form><small className="assistant-disclaimer">ShieldIQ can make mistakes. Never share OTPs, PINs, or passwords.</small></section></>}</>
}

