const genericData = [{n:'Mon',v:44},{n:'Tue',v:57},{n:'Wed',v:48},{n:'Thu',v:71},{n:'Fri',v:63},{n:'Sat',v:82},{n:'Sun',v:76}]

function DigitalArrest(){
 const {user}=useAuth()
 const [caller,setCaller]=useState('');const [transcript,setTranscript]=useState('')
 const [duration,setDuration]=useState(0);const [country,setCountry]=useState('India');const [location,setLocation]=useState('')
 const [videoCall,setVideoCall]=useState(false);const [spoof,setSpoof]=useState(false)
 const [assertedNumber,setAssertedNumber]=useState('');const [attestation,setAttestation]=useState<'verified'|'partial'|'failed'|'unavailable'>('unavailable');const [networkType,setNetworkType]=useState<'mobile'|'landline'|'voip'|'international'|'unknown'>('unknown');const [simSwap,setSimSwap]=useState(false)
 const [liveSession,setLiveSession]=useState('');const [consent,setConsent]=useState(false);const [livePreview,setLivePreview]=useState<any>(null);const streamedLength=useRef(0);const [transactionReference,setTransactionReference]=useState('')
 const [result,setResult]=useState<DigitalArrestResult|null>(null);const [history,setHistory]=useState<any[]>([])
 const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('')
 const [recording,setRecording]=useState(false);const audioInput=useRef<HTMLInputElement>(null);const recorder=useRef<MediaRecorder|null>(null)
 const dashboard=useApi(()=>services.digitalArrest.dashboard(),[])
 const refreshHistory=async(number=caller)=>{if(number.replace(/\D/g,'').length>=7)setHistory(await services.digitalArrest.history(number))}
 useEffect(()=>{const socket=new WebSocket(websocketUrl('digital-arrest'));socket.onmessage=()=>void dashboard.retry();return()=>socket.close()},[dashboard.retry])
 const telecomSignals=()=>({network_asserted_number:assertedNumber||undefined,attestation,network_type:networkType,recent_sim_swap:simSwap,origination_country:country||undefined})
 const analyze=async(e?:FormEvent)=>{e?.preventDefault();if(!caller||!transcript.trim())return;setLoading(true);setError('');setNotice('');try{const value=await services.digitalArrest.analyze({caller_number:caller,transcript,duration,video_call:videoCall,location:location||undefined,country:country||undefined,spoof_detected:spoof?true:undefined,telecom_signals:telecomSignals()});setResult(value);await Promise.all([refreshHistory(caller),dashboard.retry()])}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 const analyzeAudio=async(file?:File)=>{if(!file||!caller)return;setLoading(true);setError('');try{const value=await services.digitalArrest.analyzeAudio(file,{caller_number:caller,duration,video_call:videoCall,location:location||undefined,country:country||undefined,spoof_detected:spoof?true:undefined});setResult(value);setTranscript('Audio transcribed and stored securely. See analyzed transcript in the evidence report.');await Promise.all([refreshHistory(caller),dashboard.retry()])}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 const startLive=async()=>{if(!caller||!consent)return;setError('');try{const value=await services.digitalArrest.startLive({caller_number:caller,video_call:videoCall,consent_confirmed:consent,telecom_signals:telecomSignals()});setLiveSession(value.session_id);streamedLength.current=0;setNotice('Consent-based live analysis session started.')}catch(err){setError(errorMessage(err))}}
 const updateLive=async(final=false)=>{if(!liveSession)return;const chunk=transcript.slice(streamedLength.current).trim();if(!chunk){setError('Add new transcript text before sending a live update.');return}setLoading(true);setError('');try{const value=await services.digitalArrest.liveChunk(liveSession,{text:chunk,duration,final});streamedLength.current=transcript.length;setLivePreview(value);setNotice(`Live risk updated: ${value.risk_score}/100 (${value.threat_level}).`)}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 const finalizeLive=async()=>{if(!liveSession)return;setLoading(true);setError('');try{if(transcript.length>streamedLength.current)await updateLive(true);const value=await services.digitalArrest.finalizeLive(liveSession);setResult(value);setLiveSession('');setLivePreview(null);setNotice('Live session finalized and stored as an investigation case.');await Promise.all([refreshHistory(caller),dashboard.retry()])}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 const toggleRecording=async()=>{if(recording){recorder.current?.stop();setRecording(false);return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks:BlobPart[]=[];const media=new MediaRecorder(stream);media.ondataavailable=e=>chunks.push(e.data);media.onstop=()=>{stream.getTracks().forEach(track=>track.stop());void analyzeAudio(new File(chunks,'recorded-call.webm',{type:'audio/webm'}))};recorder.current=media;media.start();setRecording(true)}catch(err){setError(errorMessage(err))}}
 const act=async(action:'block'|'notify_police'|'save_report')=>{if(!result)return;setNotice('');try{await services.digitalArrest.action(result.case_id,action);setNotice(action==='block'?'Number blocked and recorded.':action==='notify_police'?'Police dashboard notified.':'Evidence saved to the case.');await Promise.all([refreshHistory(),dashboard.retry()])}catch(err){setError(errorMessage(err))}}
 const report=async()=>{if(!result)return;try{await services.digitalArrest.report(result.case_id);setNotice('Scam complaint submitted and fraud-network sync attempted.');await Promise.all([refreshHistory(),dashboard.retry()])}catch(err){setError(errorMessage(err))}}
 const external=async(integration:'mha'|'bank')=>{if(!result)return;setError('');try{const value=await services.digitalArrest.externalAction(result.case_id,{integration,action:integration==='mha'?'submit_alert':'request_payment_hold',transaction_id:integration==='bank'?transactionReference:undefined,reason:'High-risk digital arrest case reviewed in ShieldIQ'});setNotice(value.status==='not_configured'?`${integration.toUpperCase()} connector is not configured; no external action was sent.`:`${integration.toUpperCase()} action status: ${value.status}.`)}catch(err){setError(errorMessage(err))}}
 const probability=Math.round((result?.scam_probability||0)*100);const stats=dashboard.data
 const highlighted=useMemo(()=>{if(!result)return null;const spans=result.suspicious_spans.filter((span,index,list)=>!list.slice(0,index).some(previous=>span.start<previous.end));const parts:React.ReactNode[]=[];let cursor=0;spans.forEach((span,index)=>{if(span.start>cursor)parts.push(<span key={`text-${index}`}>{transcript.slice(cursor,span.start)}</span>);parts.push(<mark key={`mark-${index}`} className={span.severity}>{transcript.slice(span.start,span.end)}</mark>);cursor=Math.max(cursor,span.end)});if(cursor<transcript.length)parts.push(<span key="tail">{transcript.slice(cursor)}</span>);return parts},[result,transcript])
 return <Shell title="Digital Arrest Detection" subtitle="Real-time coercion analysis, citizen warnings, and investigation-ready intelligence.">
  <div className="da-stats">{[
   ['Today’s scam calls',stats?.today_scam_calls??'—',PhoneCall,'red'],['Blocked calls',stats?.blocked_calls??'—',Ban,'green'],
   ['Average risk',stats?`${stats.average_risk}%`:'—',Radar,'amber'],['High-risk numbers',stats?.high_risk_numbers??'—',Siren,'purple']
  ].map(([label,value,Icon,tone]:any)=><article className="panel" key={label}><span className={tone}><Icon/></span><div><small>{label}</small><b>{value}</b></div></article>)}</div>
  <form onSubmit={analyze} className="da-workspace">
   <article className="panel da-call"><div className="incoming-head"><i/><span>LIVE CALL INFORMATION</span><small>ENCRYPTED</small></div><div className="da-fields"><label>Caller number<input aria-label="Caller number" required value={caller} onChange={e=>setCaller(e.target.value)} onBlur={e=>void refreshHistory(e.target.value)} placeholder="+91 98765 43210"/></label><label>Duration (seconds)<input aria-label="Call duration" type="number" min="0" max="86400" value={duration} onChange={e=>setDuration(Number(e.target.value))}/></label><label>Country<input aria-label="Caller country" value={country} onChange={e=>setCountry(e.target.value)}/></label><label>Location<input aria-label="Caller location" value={location} onChange={e=>setLocation(e.target.value)} placeholder="City or district"/></label></div><div className="da-switches"><label><input type="checkbox" checked={videoCall} onChange={e=>setVideoCall(e.target.checked)}/><Video/> Video call</label><label><input type="checkbox" checked={spoof} onChange={e=>setSpoof(e.target.checked)}/><ScanFace/> Spoof confirmed</label></div><div className="telecom-intel"><small>TELECOM PROVENANCE</small><input aria-label="Network asserted number" value={assertedNumber} onChange={e=>setAssertedNumber(e.target.value)} placeholder="Network-asserted number"/><select aria-label="Carrier attestation" value={attestation} onChange={e=>setAttestation(e.target.value as any)}><option value="unavailable">Attestation unavailable</option><option value="verified">Identity verified</option><option value="partial">Partially attested</option><option value="failed">Attestation failed</option></select><select aria-label="Network type" value={networkType} onChange={e=>setNetworkType(e.target.value as any)}><option value="unknown">Unknown network</option><option value="mobile">Mobile</option><option value="landline">Landline</option><option value="voip">VoIP</option><option value="international">International</option></select><label><input type="checkbox" checked={simSwap} onChange={e=>setSimSwap(e.target.checked)}/> Recent SIM swap</label></div><div className="live-consent"><label><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> I confirm lawful consent to analyze this call</label>{!liveSession?<button type="button" disabled={!caller||!consent} onClick={()=>void startLive()}><Activity/> Start live session</button>:<span><i/> LIVE SESSION</span>}</div>{result&&<div className="caller-rep"><span className={result.caller_reputation.label}>{result.caller_reputation.label}</span><div><small>NUMBER REPUTATION • SPOOF SCORE {result.spoof_score}/100</small><b>{result.caller_reputation.reputation_score}/100 • {result.caller_reputation.report_count} reports</b>{result.spoof_reasons.map(reason=><em key={reason}>{reason}</em>)}</div></div>}
   </article>
   <article className="panel da-probability"><small>SCAM PROBABILITY</small><div className={`da-gauge ${(result?.threat_level||livePreview?.threat_level)||'idle'}`} style={{'--score':`${(result?probability:(livePreview?.scam_probability||0)*100)*3.6}deg`} as React.CSSProperties}><div><b>{result?`${probability}%`:livePreview?`${Math.round(livePreview.scam_probability*100)}%`:'—'}</b><span>{result?.threat_level||livePreview?.threat_level||'awaiting analysis'}</span></div></div><div className="confidence"><span>AI confidence</span><b>{result?`${Math.round(result.confidence)}%`:livePreview?`${Math.round(livePreview.confidence)}%`:'—'}</b><i><em style={{width:`${result?.confidence||livePreview?.confidence||0}%`}}/></i></div><p>{result?.model_version||livePreview?.model_version||'Submit a transcript or start a consent-based live session.'}</p></article>
   <article className="panel da-transcript"><div className="panel-head"><div><h3>Live conversation</h3><p>Suspicious phrases are highlighted by severity</p></div><div className="transcript-legend"><span className="green">Safe</span><span className="yellow">Suspicious</span><span className="red">Critical</span></div></div><textarea aria-label="Call transcript" required value={transcript} onChange={e=>setTranscript(e.target.value)} placeholder="Paste the live transcript here, or upload/record a call…"/>{highlighted&&<div className="highlighted-transcript">{highlighted}</div>}<input ref={audioInput} hidden type="file" accept="audio/wav,audio/mpeg,audio/mp4,audio/webm,audio/ogg" onChange={e=>void analyzeAudio(e.target.files?.[0])}/><div className="transcript-actions"><button type="button" onClick={()=>audioInput.current?.click()}><UploadCloud/> Upload audio</button><button type="button" className={recording?'recording':''} onClick={()=>void toggleRecording()}>{recording?<PhoneOff/>:<Mic/>}{recording?'Stop & analyze':'Record call'}</button>{liveSession&&<><button type="button" disabled={loading} onClick={()=>void updateLive()}><Activity/> Update live risk</button><button type="button" disabled={loading} onClick={()=>void finalizeLive()}><Save/> Finalize case</button></>}<button className="primary-action" disabled={loading||!caller||!transcript.trim()} type="submit"><Radar/>{loading?'Analyzing…':'Analyze conversation'}</button></div></article>
   <article className="panel da-explain"><div className="panel-head"><div><h3>Explainable AI</h3><p>Evidence behind this prediction</p></div>{result&&<span className={`risk-badge ${result.threat_level}`}>{result.threat_level} risk</span>}</div>{result?<><div className="chips">{result.detected_keywords.map(keyword=><span key={keyword}>{keyword}</span>)}</div><h4>Why ShieldIQ flagged this call</h4><ul>{result.explanation.map(reason=><li key={reason}><AlertTriangle/>{reason}</li>)}</ul><div className="technique-grid"><div><small>MANIPULATION</small>{result.manipulation_techniques.map(item=><span key={item}>{item}</span>)}</div><div><small>PSYCHOLOGICAL SIGNALS</small>{Object.entries(result.psychological_signals).filter(([,score])=>score>0).map(([name,score])=><span key={name}>{name}<b>{Math.round(score*100)}%</b></span>)}</div></div></>:<div className="empty-inline">Analysis reasons, manipulation techniques, authority claims, and financial threats will appear here.</div>}</article>
  </form>
  {(error||notice)&&<div className={`da-notice ${error?'error':'success'}`}>{error||notice}</div>}
  <div className="da-lower">
   <article className="panel da-timeline"><div className="panel-head"><div><h3>Conversation timeline</h3><p>Detected progression of the scam</p></div></div>{result?.conversation_stages.length?<div>{result.conversation_stages.map((stage,index)=><section key={`${stage.stage}-${index}`}><span>{index+1}</span><i/><div><b>{stage.stage}</b><small>{stage.evidence}</small></div></section>)}</div>:<div className="empty-inline">No conversation stages detected yet.</div>}</article>
   <article className="panel da-recommend"><Sparkles/><div><small>AI RECOMMENDATION</small><h3>{result?.threat_level==='critical'?'Immediate intervention required':result?.threat_level==='high'?'Block and escalate this caller':result?'Verify the caller independently':'Waiting for analysis'}</h3><p>{result?.recommendation||'ShieldIQ will generate clear, risk-aware safety guidance after analysis.'}</p></div></article>
  </div>
  <article className="panel da-emergency"><div><Siren/><span><b>Emergency actions</b><small>Every action is authenticated and written to the audit log.</small></span></div><button disabled={!result} onClick={()=>void act('block')}><Ban/> Block number</button><button disabled={!result} onClick={()=>void report()}><AlertTriangle/> Report scam</button><button disabled={!result} onClick={()=>void act('notify_police')}><Landmark/> Notify police</button><button disabled={!result} onClick={()=>void act('save_report')}><Save/> Save evidence</button><button disabled={!result} onClick={()=>result&&void services.digitalArrest.evidence(result.case_id)}><Download/> Evidence PDF</button>{result&&user&&['police','administrator'].includes(user.role)&&<button onClick={()=>void external('mha')}><Globe2/> MHA alert</button>}{result&&user&&['police','bank','administrator'].includes(user.role)&&<><input aria-label="Transaction or account reference" value={transactionReference} onChange={e=>setTransactionReference(e.target.value)} placeholder="Transaction / account ref"/><button disabled={!transactionReference} onClick={()=>void external('bank')}><Landmark/> Request bank hold</button></>}</article>
  <div className="da-bottom">
   <article className="panel da-history"><div className="panel-head"><div><h3>Previous reports</h3><p>{caller?`Intelligence for ${caller}`:'Enter a caller number to search'}</p></div><button type="button" onClick={()=>void refreshHistory()}>Refresh</button></div>{history.length?<div className="table-scroll"><table><thead><tr><th>DATE</th><th>RISK</th><th>THREAT</th><th>SPOOF</th><th>STATUS</th></tr></thead><tbody>{history.map(item=><tr key={item.id}><td>{new Date(item.created_at).toLocaleString()}</td><td><b>{item.risk_score}%</b></td><td><span className={`risk-badge ${item.threat_level}`}>{item.threat_level}</span></td><td>{item.spoof_detected?'Detected':'No signal'}</td><td>{item.status}</td></tr>)}</tbody></table></div>:<div className="empty-inline">No previous complaints found for this number.</div>}</article>
   <article className="panel da-analytics"><div className="panel-head"><div><h3>Live intelligence</h3><p>Cases during the last seven days</p></div></div><ResponsiveContainer width="100%" height={190}><AreaChart data={stats?.daily_cases||[]}><defs><linearGradient id="dafill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#06b6d4" stopOpacity=".35"/><stop offset="1" stopColor="#06b6d4" stopOpacity="0"/></linearGradient></defs><CartesianGrid stroke="#1a2940" vertical={false}/><XAxis dataKey="date" stroke="#63708a" tickLine={false} axisLine={false}/><YAxis allowDecimals={false} stroke="#63708a" tickLine={false} axisLine={false}/><Tooltip contentStyle={{background:'#101b2e',border:'1px solid #263650',borderRadius:12}}/><Area dataKey="count" stroke="#06b6d4" fill="url(#dafill)"/></AreaChart></ResponsiveContainer><div className="keyword-cloud">{stats?.common_keywords.map(item=><span key={item.keyword}>{item.keyword}<b>{item.count}</b></span>)}</div></article>
  </div>
 </Shell>
}

function Counterfeit(){
 const input=useRef<HTMLInputElement>(null);const uvInput=useRef<HTMLInputElement>(null);const irInput=useRef<HTMLInputElement>(null);const [preview,setPreview]=useState('');const [result,setResult]=useState<CurrencyResult|null>(null);const [uvFile,setUvFile]=useState<File|null>(null);const [irFile,setIrFile]=useState<File|null>(null)
 const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [location,setLocation]=useState('')
 const history=useApi(()=>services.currency.history(),[]);const statistics=useApi(()=>services.currency.statistics(),[])
 const upload=async(file?:File)=>{if(!file)return;if(preview)URL.revokeObjectURL(preview);setPreview(URL.createObjectURL(file));setLoading(true);setError('');setResult(null);try{setResult(uvFile||irFile?await services.currency.analyzeMultispectral(file,uvFile,irFile,location||undefined):await services.currency.analyze(file,location||undefined));await Promise.all([history.retry(),statistics.retry()])}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 const drop=(event:React.DragEvent)=>{event.preventDefault();void upload(event.dataTransfer.files?.[0])}
 const stats=statistics.data;const authenticity=result?.authenticity_score||0
 const featureNames:Record<string,string>={security_thread:'Security thread',watermark:'Watermark',latent_image:'Latent image',micro_lettering:'Micro lettering',see_through_register:'See-through register',color_shift_ink:'Color shift ink',ashoka_pillar:'Ashoka pillar',governor_signature:'Governor signature',gandhi_portrait:'Gandhi portrait',serial_number:'Serial number',hidden_pattern:'Hidden pattern',optical_variable_ink:'Optical variable ink'}
 return <Shell title="Counterfeit Currency Detection" subtitle="Image-derived forensic inspection for Indian banknotes.">
  <div className="currency-stats">{[['Total notes scanned',stats?.total_notes_scanned??'—',Layers3],['Counterfeit alerts',stats?.fake_notes_found??'—',Siren],['Detection accuracy',stats?.detection_accuracy==null?'Awaiting labels':`${stats.detection_accuracy}%`,Radar],['Top counterfeit denomination',stats?.most_counterfeited_denomination||'—',Banknote]].map(([label,value,Icon]:any)=><article className="panel" key={label}><Icon/><div><small>{label}</small><b>{value}</b></div></article>)}</div>
  <div className="currency-workspace">
   <article className="panel currency-intake"><div className="panel-head"><div><h3>Secure note intake</h3><p>One fully visible Indian banknote per scan</p></div><span>CV PIPELINE</span></div><label>Scan location<input aria-label="Scan location" value={location} onChange={e=>setLocation(e.target.value)} placeholder="Branch, city, or district"/></label><div className="spectral-inputs"><input ref={uvInput} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setUvFile(e.target.files?.[0]||null)}/><input ref={irInput} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setIrFile(e.target.files?.[0]||null)}/><button type="button" className={uvFile?'ready':''} onClick={()=>uvInput.current?.click()}><Zap/> {uvFile?`UV: ${uvFile.name}`:'Add physical UV capture'}</button><button type="button" className={irFile?'ready':''} onClick={()=>irInput.current?.click()}><ScanFace/> {irFile?`IR: ${irFile.name}`:'Add infrared capture'}</button><small>Optional sensor images are measured separately; absent UV/IR data is never simulated.</small></div><div onClick={()=>input.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={drop} className={`currency-drop ${preview?'has-image':''}`}><input ref={input} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>void upload(e.target.files?.[0])}/>{preview?<img src={preview} alt="Original uploaded currency note"/>:<><div><UploadCloud/></div><h3>Drop the visible-light image here</h3><p>JPG, PNG or WebP • minimum 480×200 • up to 10 MB</p></>}<button type="button">{preview?'Choose another image':'Browse image'}</button></div>{loading&&<div className="currency-progress"><span/><div>{['Boundary detection','Perspective correction','OCR and denomination','Security features',uvFile||irFile?'UV / IR evidence':'Forensic explanation'].map((step,index)=><p key={step} style={{animationDelay:`${index*.16}s`}}><i/>{step}</p>)}</div></div>}{error&&<div className="currency-error"><AlertTriangle/><span><b>Image could not be analyzed</b>{error}</span></div>}</article>
   <article className="panel currency-verdict"><div className="panel-head"><div><h3>Authenticity verdict</h3><p>Weighted independent feature evidence</p></div>{result&&<span className={`currency-label ${result.prediction.toLowerCase().replaceAll(' ','-')}`}>{result.prediction}</span>}</div>{result&&!result.legal_tender&&<div className="tender-warning"><AlertTriangle/><div><b>NOT VALID FOR CIRCULATION</b><span>{result.currency_status}</span></div></div>}<div className="auth-score" style={{'--auth':`${authenticity*3.6}deg`} as React.CSSProperties}><div><b>{result?authenticity:'—'}</b><small>{result&&!result.legal_tender?'VALIDITY':'AUTHENTICITY'}</small></div></div><div className="currency-meta"><span>Confidence<b>{result?`${result.confidence}%`:'—'}</b></span><span>Denomination<b>{result?.denomination||'—'}</b></span><span>Fake probability<b>{result?(result.legal_tender?`${Math.round(result.counterfeit_probability*100)}%`:'N/A'):'—'}</b></span></div>{result&&<><div className="serial-card"><Fingerprint/><div><small>EXTRACTED SERIAL NUMBER</small><b>{result.serial_number||'Not assessed'}</b></div><span className={result.serial_duplicate||!result.serial_valid?'fail':'pass'}>{result.serial_duplicate?'DUPLICATE':result.serial_valid?'VALID':'OCR UNAVAILABLE'}</span></div><button className="currency-report" onClick={()=>void services.currency.report(result.case_id)}><Download/> Download forensic PDF</button></>}</article>
  </div>
  {result&&<div className="currency-imagery"><article className="panel"><div className="panel-head"><div><h3>Original image</h3><p>Detected boundary overlay</p></div></div><div className="currency-image original"><img src={preview} alt="Original note"/><span style={{left:`${result.bounding_box.x/Number(result.quality.width)*100}%`,top:`${result.bounding_box.y/Number(result.quality.height)*100}%`,width:`${result.bounding_box.width/Number(result.quality.width)*100}%`,height:`${result.bounding_box.height/Number(result.quality.height)*100}%`}}/></div></article><article className="panel"><div className="panel-head"><div><h3>Detected note</h3><p>Aligned and normalized</p></div></div><div className="currency-image"><img src={result.detected_note} alt="Perspective-corrected note"/></div></article><article className="panel"><div className="panel-head"><div><h3>Forensic saliency</h3><p>{result.explainability_method}</p></div></div><div className="currency-image"><img src={result.heatmap} alt="Forensic evidence heatmap"/></div></article></div>}
  <div className="currency-details">
   <article className="panel feature-inspection"><div className="panel-head"><div><h3>Security feature inspection</h3><p>Each region is measured independently</p></div></div>{result?Object.entries(result.features).map(([name,feature])=><div className="currency-feature" key={name}><span className={feature.status==='PASS'?'pass':feature.status==='FAIL'?'fail':'neutral'}>{feature.status==='PASS'?<Check/>:feature.status==='FAIL'?<X/>:<Cpu/>}</span><div><b>{featureNames[name]||name}</b><small>{feature.value||`${feature.confidence.toFixed(0)}% detection confidence`}</small></div><i><em style={{width:`${feature.confidence}%`}}/></i><strong>{feature.status}</strong></div>):<div className="empty-inline">Upload a clear note to inspect all twelve security features.</div>}</article>
   <article className="panel currency-explain"><div className="panel-head"><div><h3>AI explanation</h3><p>Reasons supporting the verdict</p></div></div>{result?<><ul>{result.explanation.map(reason=><li key={reason}><AlertTriangle/>{reason}</li>)}</ul><div className="quality-grid">{Object.entries(result.quality).filter(([,value])=>typeof value==='number').map(([name,value])=><span key={name}>{name.replaceAll('_',' ')}<b>{typeof value==='number'&&value<=1?`${Math.round(value*100)}%`:String(value)}</b></span>)}</div><small className="model-version">{result.model_version}</small></>:<div className="empty-inline">Measured evidence and image-quality diagnostics will appear here.</div>}</article>
  </div>
  {result&&Object.keys(result.spectral_analysis||{}).length>0&&<article className="panel spectral-results"><div className="panel-head"><div><h3>Physical UV / IR evidence</h3><p>Spectral captures are reported independently from the visible-image verdict</p></div><span>NOT SIMULATED</span></div><div>{['uv','infrared'].map(channel=>{const evidence=result.spectral_analysis[channel];return <section key={channel}><b>{channel.toUpperCase()}</b><em className={(evidence?.status||'not-assessed').toLowerCase().replace(' ','-')}>{evidence?.status||'NOT ASSESSED'}</em><p>{evidence?.explanation||evidence?.reason||`No physical ${channel} capture supplied.`}</p></section>})}</div><small>{result.spectral_analysis.decision_policy}</small></article>}
   <article className="panel currency-history"><div className="panel-head"><div><h3>Detection history</h3><p>Persisted scans and duplicate serial intelligence</p></div><button onClick={history.retry}>Refresh</button></div><div className="table-scroll">{history.data?.length?<table><thead><tr><th>TIME</th><th>DENOMINATION</th><th>VERDICT</th><th>AUTHENTICITY</th><th>SERIAL</th><th>LOCATION</th></tr></thead><tbody>{history.data.map(item=><tr key={item.id}><td>{new Date(item.created_at).toLocaleString()}</td><td>{item.denomination||'—'}</td><td><span className={`currency-label ${item.prediction.toLowerCase().replaceAll(' ','-')}`}>{item.prediction}</span>{!item.legal_tender&&<em>not legal tender</em>}</td><td>{item.authenticity_score}/100</td><td>{item.serial_number||'Not assessed'}{item.serial_duplicate&&<em> duplicate</em>}</td><td>{item.location||'—'}</td></tr>)}</tbody></table>:<div className="empty-inline">No currency scans have been recorded yet.</div>}</div></article>
 </Shell>
}

function NetworkPage(){
 const {data,loading,error,retry}=useApi<any>(()=>services.graph(),[])
 const feeds=useApi<any[]>(()=>services.graphOperations.feeds(),[])
 const ingestion=useApi<any>(()=>services.graphOperations.ingestion(),[])
 const exchanges=useApi<any[]>(()=>services.graphOperations.exchanges(),[])
 const [selected,setSelected]=useState<any>(null)
 const [evidenceFile,setEvidenceFile]=useState<File|null>(null);const [caseRef,setCaseRef]=useState('');const [evidenceStatus,setEvidenceStatus]=useState<any>(null)
 const nodes=useMemo(()=>{const source=(data?.nodes||[]).slice(0,28);return source.map((node:any,i:number)=>({...node,x:400+Math.cos(i/source.length*Math.PI*2)*(110+(i%3)*70),y:230+Math.sin(i/source.length*Math.PI*2)*(90+(i%3)*45)}))},[data])
 const byId=new globalThis.Map(nodes.map((n:any)=>[n.id,n]))
 const acquire=async()=>{if(!evidenceFile||!caseRef.trim())return;try{const stored=await services.graphOperations.acquireEvidence({file:evidenceFile,case_reference:caseRef,title:evidenceFile.name,evidence_type:'digital_file'});const verified=await services.graphOperations.verifyEvidence(stored.evidence_id);setEvidenceStatus(verified);setEvidenceFile(null)}catch(err){setEvidenceStatus({error:errorMessage(err)})}}
 if(loading)return <Shell title="Fraud Network Intelligence" subtitle="Analyzing cross-entity relationships."><LoadingPanel/></Shell>
 if(error)return <Shell title="Fraud Network Intelligence" subtitle="Explore hidden relationships."><ErrorPanel message={error} retry={retry}/></Shell>
 return <Shell title="Fraud Network Intelligence" subtitle="Multi-source entity resolution, jurisdiction exchange and court-evidence integrity."><div className="network-kpis">{[[String(feeds.data?.length||0),'Registered agency feeds',Database],[String(ingestion.data?.total_events||0),'Normalized live events',Activity],[String(ingestion.data?.batches?.filter((x:any)=>x.graph_status==='synchronized').length||0),'Neo4j synchronized',Network],[String(exchanges.data?.length||0),'Case exchanges',Share2]].map(([value,label,Icon]:any)=><article className="panel" key={label}><Icon/><span><b>{value}</b><small>{label}</small></span></article>)}</div><div className="network-wrap"><article className="panel graph"><div className="graph-controls"><span><Network/> {data?.statistics?.nodes||0} nodes • {data?.statistics?.clusters||0} clusters</span><em>PERSISTED EVENTS + NEO4J</em></div>{!nodes.length&&<div className="graph-empty"><Network/><h3>No operational graph events yet</h3><p>Register an authorized bank, telecom, device, or agency feed and ingest the first batch.</p></div>}<svg viewBox="0 0 800 460" className="network-svg">{(data?.edges||[]).slice(0,60).map((edge:any,i:number)=>{const a:any=byId.get(edge.source),b:any=byId.get(edge.target);return a&&b?<line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y}/>:null})}{nodes.map((node:any)=><g key={node.id} onClick={()=>setSelected(node)} className={(node.type||node.label||'device').toLowerCase()}><circle cx={node.x} cy={node.y} r={16+Math.min((node.risk_score||0)/8,13)}/><text x={node.x} y={node.y+4}>{String(node.type||node.label||'?').slice(0,3)}</text></g>)}</svg><div className="graph-legend"><span><i className="victim"/>Citizen</span><span><i className="phone"/>Phone/CDR</span><span><i className="upi"/>UPI</span><span><i className="bank"/>Bank</span><span><i className="device"/>Device</span></div></article><article className="panel entity">{selected?<><button className="entity-close" onClick={()=>setSelected(null)}><X/></button><div className="entity-avatar">{String(selected.type||'EN').slice(0,2).toUpperCase()}</div><small>ENTITY PROFILE</small><h2>{selected.label||selected.id}</h2><span className={selected.risk_score>=70?'tag-risk':'tag-safe'}>{selected.risk_score>=70?'HIGH RISK':'MONITORED'}</span><div className="entity-score"><span>Risk score</span><b>{selected.risk_score||0} / 100</b></div><h4>GRAPH SIGNALS</h4><div className="connections"><span><Network/> PageRank {selected.pagerank||0}</span><span><Activity/> Centrality {selected.centrality||0}</span><span><FileText/> Cluster {selected.cluster_id||'—'}</span></div></>:<div className="empty-state"><Network/><h3>Select an entity</h3><p>Choose a node to inspect its live risk and relationships.</p></div>}</article></div><div className="graph-operations"><article className="panel"><div className="panel-head"><div><h3>Multi-agency ingestion</h3><p>Bank, telecom, device and agency feeds</p></div><Database/></div>{feeds.data?.map((x:any)=><div className="feed-row" key={x.id}><i className={x.active?'active':''}/><span><b>{x.name}</b><small>{x.agency_type} • {x.data_type} • {x.jurisdiction}</small></span><em>{x.last_ingested_at?'LIVE':'READY'}</em></div>)}{!feeds.data?.length&&<div className="empty-inline">Register feeds through the secured Graph API to begin live ingestion.</div>}</article><article className="panel"><div className="panel-head"><div><h3>Cross-jurisdiction exchange</h3><p>Hashed packages with acknowledgement</p></div><Link2/></div>{exchanges.data?.slice(0,6).map((x:any)=><div className="exchange-row" key={x.id}><span><b>{x.case_reference}</b><small>{x.source_jurisdiction} → {x.target_jurisdiction}</small></span>{x.status==='shared'?<button onClick={()=>void services.graphOperations.acknowledgeExchange(x.id).then(exchanges.retry)}>Acknowledge</button>:<em>ACKNOWLEDGED</em>}</div>)}{!exchanges.data?.length&&<div className="empty-inline">No jurisdiction packages have been shared.</div>}</article><article className="panel evidence-acquire"><div className="panel-head"><div><h3>Evidence chain of custody</h3><p>SHA-256 file integrity and linked custody hashes</p></div><FileCheck2/></div><label>Case reference<input value={caseRef} onChange={e=>setCaseRef(e.target.value)} placeholder="e.g. FIR-DL-2026-1042"/></label><label>Evidence file<input type="file" onChange={e=>setEvidenceFile(e.target.files?.[0]||null)}/></label><button className="primary" disabled={!caseRef.trim()||!evidenceFile} onClick={()=>void acquire()}><ShieldCheck/> Acquire and verify</button>{evidenceStatus&&<div className={evidenceStatus.error?'evidence-result invalid':'evidence-result'}>{evidenceStatus.error?<><AlertTriangle/> {evidenceStatus.error}</>:<><Check/> Chain valid: {String(evidenceStatus.chain_valid)} • File hash valid: {String(evidenceStatus.file_hash_valid)}</>}</div>}</article></div></Shell>
}

function CrimeMap(){
 const {data,loading,error,retry}=useApi<any>(()=>services.geospatial.hotspots(),[])
 const heatmap=useApi<any>(()=>services.heatmap(),[])
 const patrol=useApi<any>(()=>services.geospatial.patrolPlan(),[])
 const shares=useApi<any>(()=>services.geospatial.shares(),[])
 const [district,setDistrict]=useState('All districts')
 if(loading)return <Shell title="Crime Intelligence Map" subtitle="Predicting emerging hotspots."><LoadingPanel/></Shell>
 if(error)return <Shell title="Crime Intelligence Map" subtitle="Live geospatial risk."><ErrorPanel message={error} retry={retry}/></Shell>
 const all=data||[];const shown=district==='All districts'?all:all.filter((x:any)=>x.district===district)
 const features=(heatmap.data?.features||[]).filter((x:any)=>district==='All districts'||x.properties.district===district)
 const project=(coordinates:number[])=>({left:`${Math.max(4,Math.min(96,(coordinates[0]-68)/29*100))}%`,top:`${Math.max(4,Math.min(96,(37-coordinates[1])/29*100))}%`})
 return <Shell title="Geospatial Intelligence" subtitle="Persisted GIS incidents, patrol priorities and inter-district coordination."><div className="geo-toolbar panel"><div><Radio/><span><b>Live GIS feeds</b><small>{features.length} persisted incident points</small></span></div><select value={district} onChange={e=>setDistrict(e.target.value)}><option>All districts</option>{all.map((x:any)=><option key={x.district}>{x.district}</option>)}</select><button onClick={()=>{heatmap.retry();patrol.retry();shares.retry()}}><Radar/> Refresh intelligence</button></div><div className="map-layout"><article className="map-canvas real-gis-map"><div className="map-grid"/>{features.map((feature:any)=><span key={feature.properties.id} className={`gis-point risk-${feature.properties.risk_score>=70?'high':'medium'}`} title={`${feature.properties.district}: ${feature.properties.crime_type}`} style={project(feature.geometry.coordinates)}/>)}{patrol.data?.recommendations?.map((item:any)=><div key={item.priority} className="patrol-marker" style={project([item.longitude,item.latitude])}><Navigation/><b>{item.priority}</b></div>)}<div className="map-legend"><span><i className="incident-dot"/> Incident</span><span><Navigation/> Patrol priority</span></div></article><article className="panel hotspots"><h3>Top hotspots</h3><p>Calculated from persisted incident records</p>{shown.slice(0,8).map((x:any,i:number)=><div className="hot-row" key={x.district}><b>{String(i+1).padStart(2,'0')}</b><span>{x.district}<small>{x.incidents} incidents analyzed</small></span><em>{x.predicted_risk}</em></div>)}{!shown.length&&<div className="empty-inline">No incident data matches this district.</div>}</article></div><div className="geo-operations"><article className="panel"><div className="panel-head"><div><h3>Patrol optimisation</h3><p>Ranked staging recommendations from recent incidents</p></div><Navigation/></div>{patrol.data?.recommendations?.map((x:any)=><div className="patrol-row" key={x.priority}><b>#{x.priority}</b><span>{x.district}<small>{x.recommended_action}</small></span><em>{x.priority_score}</em></div>)}{!patrol.data?.recommendations?.length&&<div className="empty-inline">No recent incidents available for route recommendations.</div>}<small className="operational-limit">{patrol.data?.limitations}</small></article><article className="panel"><div className="panel-head"><div><h3>Inter-district intelligence</h3><p>Acknowledged, auditable sharing workflow</p></div><Share2/></div>{shares.data?.slice(0,6).map((x:any)=><div className="share-row" key={x.id}><span className={`risk-${x.severity}`}>{x.severity}</span><div><b>{x.title}</b><small>{x.source_district} → {x.target_district}</small></div>{x.status!=='acknowledged'?<button onClick={()=>void services.geospatial.acknowledge(x.id).then(shares.retry)}>Acknowledge</button>:<em>ACKNOWLEDGED</em>}</div>)}{!shares.data?.length&&<div className="empty-inline">No intelligence packages have been shared.</div>}</article></div></Shell>
}

function Assistant(){
 const uploadRef=useRef<HTMLInputElement>(null);const recorderRef=useRef<MediaRecorder|null>(null);const mediaStreamRef=useRef<MediaStream|null>(null);const recognitionRef=useRef<any>(null);const pendingChunksRef=useRef<Promise<any>[]>([]);const [input,setInput]=useState('');const [file,setFile]=useState<File|null>(null);const [loading,setLoading]=useState(false);const [language,setLanguage]=useState('en');const [recording,setRecording]=useState(false);const [speechError,setSpeechError]=useState('');const [streamId,setStreamId]=useState('');const [liveTranscript,setLiveTranscript]=useState('');const [voiceSignal,setVoiceSignal]=useState<any>(null);const [messages,setMessages]=useState<any[]>([{role:'bot',text:'Namaste! Paste suspicious content, attach evidence, or start a live voice safety check.'}])
 useEffect(()=>()=>{const recorder=recorderRef.current;if(recorder){recorder.ondataavailable=null;recorder.onstop=null;if(recorder.state!=='inactive')recorder.stop()}recognitionRef.current?.abort?.();mediaStreamRef.current?.getTracks().forEach(track=>track.stop());recorderRef.current=null;recognitionRef.current=null;mediaStreamRef.current=null},[])
 const languages=[['en','English'],['hi','हिन्दी'],['bn','বাংলা'],['te','తెలుగు'],['mr','मराठी'],['ta','தமிழ்'],['gu','ગુજરાતી'],['ur','اردو'],['kn','ಕನ್ನಡ'],['or','ଓଡ଼ିଆ'],['ml','മലയാളം'],['pa','ਪੰਜਾਬੀ']]
 const send=async(text=input)=>{if((!text.trim()&&!file)||loading)return;const prompt=text.trim()||`Analyze attached ${file?.type||'file'}`;const currentFile=file;setMessages(m=>[...m,{role:'user',text:prompt,file:currentFile?.name}]);setInput('');setFile(null);setLoading(true);try{const result=await services.chat(prompt,currentFile,language);setMessages(m=>[...m,{role:'bot',text:result.response,confidence:Math.round(result.confidence*100),risk:result.risk_level,recommendations:result.recommendations,analysisId:result.analysis_id}])}catch(err){setMessages(m=>[...m,{role:'bot',text:errorMessage(err),error:true}])}finally{setLoading(false)}}
 const startVoice=async()=>{setSpeechError('');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setSpeechError('Live recording is not supported by this browser. Upload a WAV, MP3, M4A, OGG, or WebM recording instead.');return}try{const media=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});mediaStreamRef.current=media;const started=await services.speech.start(language);setStreamId(started.stream_id);setLiveTranscript('');pendingChunksRef.current=[];const recorder=new MediaRecorder(media);recorderRef.current=recorder;const Recognition=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(Recognition){const recognition=new Recognition();recognition.continuous=true;recognition.interimResults=true;recognition.lang=({en:'en-IN',hi:'hi-IN',bn:'bn-IN',te:'te-IN',mr:'mr-IN',ta:'ta-IN',gu:'gu-IN',ur:'ur-IN',kn:'kn-IN',or:'or-IN',ml:'ml-IN',pa:'pa-IN'} as Record<string,string>)[language]||'en-IN';recognition.onresult=(event:any)=>{let interim='';for(let i=event.resultIndex;i<event.results.length;i++){const text=event.results[i][0].transcript.trim();if(event.results[i].isFinal&&text){const request=services.speech.transcript(started.stream_id,text).then(result=>setLiveTranscript(result.transcript));pendingChunksRef.current.push(request)}else interim+=text+' '}if(interim)setLiveTranscript(current=>`${current} ${interim}`.trim())};recognition.onerror=(event:any)=>{if(event.error!=='aborted'&&event.error!=='no-speech')setSpeechError(`Speech recognition: ${event.error}`)};recognition.start();recognitionRef.current=recognition}recorder.ondataavailable=event=>{if(!event.data.size)return;const request=services.speech.chunk(started.stream_id,event.data).then(result=>{if(result.transcript)setLiveTranscript(result.transcript);setVoiceSignal(result.voice_forensics)}).catch(err=>setSpeechError(errorMessage(err)));pendingChunksRef.current.push(request)};recorder.onstop=async()=>{media.getTracks().forEach(track=>track.stop());try{recognitionRef.current?.stop();await Promise.allSettled(pendingChunksRef.current);const result=await services.speech.finalize(started.stream_id);setLiveTranscript(result.transcript||'');setVoiceSignal(result.voice_forensics);setMessages(m=>[...m,{role:'bot',text:result.response,confidence:Math.round(result.confidence*100),risk:result.risk_level,recommendations:result.recommendations,analysisId:result.analysis_id}])}catch(err){setSpeechError(errorMessage(err))}finally{setRecording(false);recorderRef.current=null;recognitionRef.current=null;mediaStreamRef.current=null}};recorder.start(4000);setRecording(true)}catch(err:any){mediaStreamRef.current?.getTracks().forEach(track=>track.stop());mediaStreamRef.current=null;const denied=err?.name==='NotAllowedError'||String(err?.message||err).toLowerCase().includes('permission');setSpeechError(denied?'Microphone access is blocked. Allow microphone access for 127.0.0.1 in the browser site settings, then try again—or upload a recording instead.':errorMessage(err));setRecording(false)}}
 const stopVoice=()=>{if(recorderRef.current?.state==='recording'){recorderRef.current.requestData();recorderRef.current.stop()}}
 const submitNcrb=async(id:string)=>{try{const result=await services.submitNcrb(id);setMessages(m=>[...m,{role:'bot',text:result.status==='not_configured'?'NCRB connector is not configured, so no external submission was sent.':'NCRB submission status: '+result.status}])}catch(err){setMessages(m=>[...m,{role:'bot',text:errorMessage(err),error:true}])}}
 return <Shell title="Citizen Fraud Shield" subtitle="Multilingual, multi-channel fraud assessment with auditable escalation."><div className="channel-strip panel"><span><Languages/> 12 Indian languages</span><span><MessageSquareText/> WhatsApp webhook ready</span><span><PhoneCall/> IVR webhook ready</span><span><ShieldCheck/> NCRB connector</span></div><div className="chat-layout"><article className="panel chat"><div className="chat-status"><span><Bot/></span><div><b>ShieldIQ AI</b><small><i/> Protected analysis • text, image, PDF and voice</small></div><select aria-label="Assistant language" value={language} onChange={e=>setLanguage(e.target.value)}>{languages.map(([code,label])=><option key={code} value={code}>{label}</option>)}</select></div>{recording&&<div className="live-speech"><span><i/> LIVE SPEECH</span><p>{liveTranscript||'Listening and analyzing encrypted audio chunks…'}</p><div><em>Stream {streamId.slice(0,8)}</em><b>{voiceSignal?.classification?.replaceAll('_',' ')||'collecting signal'}</b></div></div>}{speechError&&<div className="speech-error"><AlertTriangle/><span>{speechError}</span><button onClick={()=>uploadRef.current?.click()}>Upload recording</button><button aria-label="Dismiss speech error" onClick={()=>setSpeechError('')}><X/></button></div>}<div className="messages">{messages.map((msg,i)=>msg.role==='user'?<div className="user-msg" key={i}><p>{msg.text}{msg.file&&<small>📎 {msg.file}</small>}</p></div>:<div className="bot-msg" key={i}><span><Bot/></span>{msg.confidence?<div className="analysis-msg"><b><ShieldCheck/> {msg.risk} risk</b><p>{msg.text}</p>{msg.recommendations?.length>0&&<ul>{msg.recommendations.map((x:string)=><li key={x}>{x}</li>)}</ul>}<div><span>AI confidence</span><b>{msg.confidence}%</b></div><i><em style={{width:`${msg.confidence}%`}}/></i>{msg.analysisId&&<button className="ncrb-action" onClick={()=>void submitNcrb(msg.analysisId)}>Prepare NCRB submission</button>}</div>:<p className={msg.error?'message-error':''}>{msg.text}</p>}</div>)}{loading&&<div className="bot-msg"><span><Bot/></span><p>Analyzing content and safety signals…</p></div>}</div><div className="suggestions">{['Is this message fake?','Check this UPI payment request','Explain digital arrest fraud','Report a suspicious call'].map(x=><button type="button" key={x} onClick={()=>void send(x)}>{x}</button>)}</div>{file&&<div className="attachment-chip"><UploadCloud/><span>{file.name}<small>{(file.size/1024).toFixed(1)} KB</small></span><button onClick={()=>setFile(null)} aria-label="Remove attachment"><X/></button></div>}<form className="chat-input" onSubmit={e=>{e.preventDefault();void send()}}><input ref={uploadRef} hidden type="file" accept="image/png,image/jpeg,image/webp,audio/wav,audio/mpeg,audio/mp4,audio/ogg,audio/webm,application/pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button type="button" onClick={()=>uploadRef.current?.click()} aria-label="Attach file"><UploadCloud/></button><button type="button" className={recording?'recording':''} onClick={()=>recording?stopVoice():void startVoice()} aria-label={recording?'Stop live voice analysis':'Start live voice analysis'}>{recording?<Square/>:<Mic/>}</button><input aria-label="Assistant message" value={input} onChange={e=>setInput(e.target.value)} placeholder="Paste suspicious content or ask in your language..."/><button disabled={loading||(!input.trim()&&!file)} aria-label="Send message"><ArrowRight/></button></form></article><aside className="shield-tips"><div className="panel"><ShieldCheck/><h3>Privacy-aware analysis</h3><p>Audio is processed in short chunks. Avoid speaking OTPs, PINs, passwords, or financial credentials.</p></div><div className="panel"><h3>Channel integrations</h3><p><Check/> Provider-neutral WhatsApp webhook</p><p><Check/> IVR request/response adapter</p><p><Check/> Signed NCRB submission connector</p><p><Check/> Installable responsive web interface</p></div></aside></div></Shell>
}

function Reports(){
 const [search,setSearch]=useState('');const {data,loading,error,retry}=useApi(()=>services.reports(search?{search}:undefined),[search])
 return <Shell title="Citizen Reports" subtitle="Review, triage and investigate public safety submissions."><article className="panel reports"><div className="report-tools"><div className="global-search"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search reports..."/></div><button onClick={retry}><SlidersHorizontal/> Refresh</button></div>{loading?<LoadingPanel label="Loading reports…"/>:error?<ErrorPanel message={error} retry={retry}/>:<div className="table-scroll"><table><thead><tr><th>REPORT ID</th><th>REPORT</th><th>CATEGORY</th><th>LOCATION</th><th>RISK</th><th>STATUS</th><th>SUBMITTED</th></tr></thead><tbody>{data?.items.map(item=><tr key={item.id}><td>#{item.id.slice(0,8)}</td><td>{item.title}</td><td>{item.category.replace('_',' ')}</td><td>{item.location||'—'}</td><td><span className={`risk-${item.risk_score>=80?'critical':item.risk_score>=60?'high':item.risk_score>=30?'medium':'low'}`}>{item.risk_score}</span></td><td><span className="status">{item.status}</span></td><td>{new Date(item.created_at).toLocaleDateString()}</td></tr>)}</tbody></table>{!data?.items.length&&<div className="empty-inline">No reports match this search.</div>}</div>}</article></Shell>
}

function Analytics(){
 const {data,loading,error,retry}=useApi(()=>services.analytics(),[])
 if(loading)return <Shell title="Intelligence Analytics" subtitle="Calculating operational impact."><LoadingPanel/></Shell>
 if(error)return <Shell title="Intelligence Analytics" subtitle="Cross-network performance."><ErrorPanel message={error} retry={retry}/></Shell>
 const d=data!;const chart=d.monthly_trends.map(x=>({n:new Date(x.date).toLocaleDateString(undefined,{month:'short',day:'numeric'}),v:x.count}));const risk=Object.entries(d.risk_distribution).map(([name,v])=>({name,v}))
 return <Shell title="Intelligence Analytics" subtitle="Cross-network performance, trends and operational impact."><div className="analytics-kpis">{[[`₹${d.money_saved.toLocaleString('en-IN')}`,'Citizen money saved'],[String(d.protected_citizens),'Citizens protected'],[String(d.digital_arrest_cases),'Calls analyzed'],[String(d.active_investigations),'Active investigations']].map(x=><div className="panel" key={x[1]}><small>{x[1]}</small><b>{x[0]}</b><em>LIVE</em></div>)}</div><div className="analytics-grid"><article className="panel wide"><div className="panel-head"><div><h3>Fraud growth</h3><p>30-day verified report volume</p></div></div><ResponsiveContainer width="100%" height={260}><AreaChart data={chart}><CartesianGrid stroke="#1a2940" vertical={false}/><XAxis dataKey="n" stroke="#63708a"/><YAxis stroke="#63708a"/><Tooltip/><Area dataKey="v" stroke="#3976ff" fill="#3976ff33"/></AreaChart></ResponsiveContainer></article><article className="panel"><div className="panel-head"><div><h3>Risk distribution</h3><p>Current report portfolio</p></div></div><ResponsiveContainer width="100%" height={210}><PieChart><Pie data={risk} dataKey="v" nameKey="name" innerRadius={60} outerRadius={85}>{['#3976ff','#19c6d4','#9b6cff','#f05b67'].map(c=><Cell key={c} fill={c}/>)}</Pie></PieChart></ResponsiveContainer><div className="pie-labels">{risk.map(x=><span key={x.name}><i/>{x.name} {x.v}</span>)}</div></article></div></Shell>
}

function SettingsPage(){
 const {user,refreshUser,logout}=useAuth();const [name,setName]=useState(user?.full_name||'');const [state,setState]=useState(user?.state||'');const [district,setDistrict]=useState(user?.district||'');const [status,setStatus]=useState('');const [sessions,setSessions]=useState<any[]>([]);const [currentPassword,setCurrentPassword]=useState('');const [newPassword,setNewPassword]=useState('')
 useEffect(()=>{services.auth.sessions().then(setSessions).catch(()=>setSessions([]))},[])
 const save=async()=>{setStatus('Saving…');try{await services.auth.updateMe({full_name:name,state,district});await refreshUser();setStatus('Profile saved')}catch(err){setStatus(errorMessage(err))}}
 const change=async()=>{setStatus('Updating password…');try{setStatus((await services.auth.changePassword(currentPassword,newPassword)).message);setTimeout(()=>void logout(),700)}catch(err){setStatus(errorMessage(err))}}
 const logoutAll=async()=>{await services.auth.logoutAll();location.assign('/login')}
 return <Shell title="Settings" subtitle="Manage your command profile, security and active sessions."><div className="settings-layout"><nav>{['Profile','Security','Active sessions','Notifications','Language & region'].map((x,i)=><button key={x} className={i===0?'active':''}>{x}</button>)}</nav><div><article className="panel settings-form"><h3>Command profile</h3><p>Manage your verified identity across the secure workspace.</p><div className="avatar-edit"><span>{name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</span></div><div className="form-grid"><label>Full name<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Role<input disabled value={user?.role.replace('_',' ')}/></label><label>Email address<input disabled value={user?.email}/></label><label>Account state<input disabled value={user?.account_status}/></label><label>State<input value={state} onChange={e=>setState(e.target.value)}/></label><label>District<input value={district} onChange={e=>setDistrict(e.target.value)}/></label></div><button onClick={()=>void save()} className="primary">Save profile</button></article><article className="panel security-settings"><h3>Change password</h3><div className="form-grid"><label>Current password<input type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></label><label>New strong password<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></label></div><button className="secondary" disabled={!currentPassword||newPassword.length<10} onClick={()=>void change()}>Update password</button><h3>Active sessions</h3>{sessions.map(session=><div className="session-row" key={session.id}><LockKeyhole/><span><b>{session.device_name||'Web browser'}</b><small>{session.ip_address||'Private network'} • {new Date(session.last_seen_at).toLocaleString()}</small></span><em>{session.revoked_at?'Ended':'Active'}</em></div>)}<button className="danger-button" onClick={()=>void logoutAll()}>Sign out all devices</button>{status&&<span className="save-status">{status}</span>}</article></div></div></Shell>
}

function Login(){
 const [role,setRole]=useState('Police Officer');const [email,setEmail]=useState('admin@shieldiq.gov.in');const [password,setPassword]=useState('ShieldIQ!2026');const [show,setShow]=useState(false);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const navigate=useNavigate();const location=useLocation();const {login,user}=useAuth();const roles=[[CircleUserRound,'Citizen'],[Shield,'Police Officer'],[Landmark,'Bank'],[Globe2,'Telecom Provider'],[LockKeyhole,'Administrator']] as const
 useEffect(()=>{if(user)navigate('/dashboard',{replace:true})},[user,navigate])
 const submit=async(e:FormEvent)=>{e.preventDefault();setLoading(true);setError('');try{await login(email,password);navigate((location.state as any)?.from||'/dashboard',{replace:true})}catch(err){setError(errorMessage(err))}finally{setLoading(false)}}
 return <div className="login"><div className="login-art"><Logo/><div><span className="kicker">SECURE ACCESS GATEWAY</span><h1>One platform.<br/><em>Every defender.</em></h1><p>Access real-time intelligence across India's digital public safety network.</p></div><small>ENCRYPTED • ROLE-BASED ACCESS • AUDIT LOGGED</small></div><div className="login-form"><form className="login-box" onSubmit={submit}><span className="mobile-logo"><Logo/></span><h2>Welcome to ShieldIQ</h2><p>Select your workspace and sign in securely.</p><div className="role-grid">{roles.map(([Icon,r])=><button type="button" key={r} onClick={()=>setRole(r)} className={role===r?'active':''}><Icon/><span>{r}</span>{role===r&&<Check/>}</button>)}</div><label>Official email or ID<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@agency.gov.in"/></label><label>Password<div className="password"><input required type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password"/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></div></label>{error&&<div className="login-error"><AlertTriangle/>{error}</div>}<button disabled={loading} className="primary login-button" type="submit">{loading?'Establishing secure session…':'Sign in securely'} <ArrowRight/></button><p className="support">Demo credentials are created by <code>scripts/seed.py</code>.</p></form></div></div>
}

export default function App(){
 const all=['police','bank','telecom_provider','administrator'] as const
 return <Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<LoginPage/>}/><Route path="/signup" element={<SignupPage/>}/><Route path="/verify-account" element={<VerifyAccountPage/>}/><Route path="/forgot-password" element={<ForgotPasswordPage/>}/><Route path="/reset-password" element={<ForgotPasswordPage/>}/><Route path="/dashboard" element={<Protected><Dashboard/></Protected>}/><Route path="/digital-arrest" element={<Protected><DigitalArrest/></Protected>}/><Route path="/counterfeit" element={<Protected roles={['police','bank','administrator']}><Counterfeit/></Protected>}/><Route path="/network" element={<Protected roles={[...all]}><NetworkPage/></Protected>}/><Route path="/crime-map" element={<Protected roles={['police','telecom_provider','administrator']}><CrimeMap/></Protected>}/><Route path="/assistant" element={<Protected><Assistant/></Protected>}/><Route path="/reports" element={<Protected><Reports/></Protected>}/><Route path="/analytics" element={<Protected roles={[...all]}><Analytics/></Protected>}/><Route path="/settings" element={<Protected><SettingsPage/></Protected>}/><Route path="/admin/users" element={<Protected roles={['administrator']}><AdminUsersPage shell={props=><Shell {...props}/>} /></Protected>}/><Route path="*" element={<Landing/>}/></Routes>
}
